%% Method-aware gate for V1--V4
clear; clc; thisDir=fileparts(mfilename('fullpath')); outDir=fullfile(thisDir,'results');
v1=readtable(fullfile(outDir,'V1_SameBladeTransition_20251222.csv')); v2=readtable(fullfile(outDir,'V2_LeaveOneGap_20251222.csv')); v3=readtable(fullfile(outDir,'V3_LeaveOneBlade_IncrementTransfer_20251222.csv')); v4=readtable(fullfile(outDir,'V4_ExperimentalClosure_Summary_20251222.csv'));
ids=string([]); for q={v1,v2,v3,v4}, if ismember('methodId',q{1}.Properties.VariableNames), ids=[ids;string(q{1}.methodId(1))]; end, end; ids=unique(ids(ids~="")); if isempty(ids), methodId="unspecified_method"; else, methodId=ids(1); end
v1p90=prctile(v1.relativeRMSEpct,90); v2p90=prctile(v2.relativeRMSEpct,90); v3p90=prctile(v3.relativeToBaseline,90); v1pass=v1p90<=10; v2pass=v2p90<=10; v3pass=v3p90<0.50; v4pass=(v4.nWindows>0)&&(v4.nEOMatches==v4.nWindows)&&v4.meanAbsFrequencyDiffHz<=0.05&&v4.meanAbsAmplitudeDiffMm<=0.001&&v4.meanAbsRMSEDiffmV<=0.10;
status=string({'V1_same_blade_transition';'V2_leave_one_gap';'V3_leave_one_blade_increment';'V4_high_speed_closure_consistency'}); pass=[v1pass;v2pass;v3pass;v4pass]; evidence=string({sprintf('N=%d, P90 relative RMSE=%.3f%%',height(v1),v1p90);sprintf('N=%d, P90 relative RMSE=%.3f%%',height(v2),v2p90);sprintf('N=%d, P90 transfer/baseline=%.3f',height(v3),v3p90);sprintf('N=%d, EO=%d, |df|=%.6f Hz',v4.nWindows,v4.nEOMatches,v4.meanAbsFrequencyDiffHz)});
runDate=string(datetime('now','Format','yyyy-MM-dd HH:mm:ss')); [~,gitHash]=system('git rev-parse --short HEAD'); gitHash=strtrim(string(gitHash)); T=table(repmat(methodId,4,1),repmat(runDate,4,1),repmat(string(gitHash),4,1),status,pass,evidence,'VariableNames',{'methodId','runDate','gitHash','validation','pass','evidence'}); writetable(T,fullfile(outDir,['ValidationGate_' char(methodId) '_20251222.csv'])); writetable(T,fullfile(outDir,'ValidationGate_20251222.csv')); disp(T);
